commands:
pwsh -NoLogo -NoProfile -Command "
\$files = @('./podex.ps1','./api/_lib/pantry-store.ps1','./api/_lib/pantry-render.ps1')
foreach(\$f in \$files){
  \$err = \$null
  [System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path \$f), [ref]\$null, [ref]\$err) | Out-Null
  if(\$err){ Write-Host (\$f + ': PARSE ERRORS'); \$err | ForEach-Object { Write-Host \$_.Message } } else { Write-Host (\$f + ': OK') }
}
"

cd <WORKSPACE>/pantry
pwsh -NoLogo -NoProfile -Command "
Import-Module PSScriptAnalyzer -MaximumVersion 1.99.99 -Force
foreach(\$f in @('./podex.ps1','./api/_lib/pantry-store.ps1','./api/_lib/pantry-render.ps1')){
  \$r = Invoke-ScriptAnalyzer -Path \$f
  Write-Host ('=== ' + \$f + ' ===')
  if(\$r){ \$r | Format-Table RuleName, Severity, Line, Message -AutoSize | Out-String | Write-Host } else { Write-Host 'no findings' }
}
"
